{
  "tasks": [
    {
      "task_id": "T1",
      "title": "工单整体概况统计",
      "business_question": "客服工单的总数量、涉及团队数及状态分布情况如何？",
      "priority": "P0",
      "priority_reason": "删除此任务将无法了解数据集的基本规模和主要类别构成，无法回答“主要特征”这一核心探索目标。",
      "requirement_ids": [
        "C01"
      ],
      "depends_on": [],
      "missing_inputs": [],
      "steps": [
        {
          "step_id": "S1_1",
          "operation": "aggregate",
          "params": {
            "metrics": [
              {
                "function": "count",
                "field": null,
                "alias": "total_ticket_count"
              },
              {
                "function": "distinct_count",
                "field": "field_0002",
                "alias": "unique_team_count"
              },
              {
                "function": "distinct_count",
                "field": "field_0003",
                "alias": "unique_status_count"
              }
            ]
          }
        }
      ]
    },
    {
      "task_id": "T2",
      "title": "按团队分析工单数量与响应时间差异",
      "business_question": "不同团队的工单数量分布如何？各团队的平均响应分钟数是否存在显著差异？",
      "priority": "P0",
      "priority_reason": "这是探索数据“差异”的核心维度。通过分组对比不同团队的负载（数量）和效率（响应时间），直接支持识别主要业务特征的决策需求。",
      "requirement_ids": [
        "C01"
      ],
      "depends_on": [],
      "missing_inputs": [],
      "steps": [
        {
          "step_id": "S2_1",
          "operation": "group_aggregate",
          "params": {
            "metrics": [
              {
                "function": "count",
                "field": null,
                "alias": "ticket_count_by_team"
              },
              {
                "function": "avg",
                "field": "field_0005",
                "alias": "avg_response_minutes_by_team"
              }
            ],
            "dimensions": [
              "field_0002"
            ]
          }
        }
      ]
    },
    {
      "task_id": "T3",
      "title": "按优先级与状态交叉分析工单分布",
      "business_question": "不同优先级下的工单在各状态中的分布情况如何？高优先级工单是否更容易处于未解决状态？",
      "priority": "P1",
      "priority_reason": "提供比单一维度更细致的特征洞察，帮助理解业务逻辑（如优先级对处理流程的影响），属于补充性但高质量的分析。",
      "requirement_ids": [
        "C01"
      ],
      "depends_on": [],
      "missing_inputs": [],
      "steps": [
        {
          "step_id": "S3_1",
          "operation": "group_aggregate",
          "params": {
            "metrics": [
              {
                "function": "count",
                "field": null,
                "alias": "ticket_count_by_priority_status"
              }
            ],
            "dimensions": [
              "field_0004",
              "field_0003"
            ]
          }
        }
      ]
    }
  ]
}
